contracts/OnlyHoldFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./OnlyHoldNFT.sol";
import "./OnlyHoldSubscription.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title OnlyHoldFactory
 * @dev Factory contract that deploys creator contracts in one transaction.
 *
 * A creator calls `launchCreator()` to simultaneously deploy:
 *   - An OnlyHoldNFT contract (if NFT membership is desired)
 *   - An OnlyHoldSubscription contract (if stablecoin sub is desired)
 *
 * The factory also serves as the on-chain registry of all creators,
 * making it easy to enumerate and verify creator contracts.
 *
 * Only verified (non-blacklisted) creators can be registered.
 * Platform treasury is set at factory deployment and inherited by all contracts.
 */
contract OnlyHoldFactory is Ownable {
    // ─── Structs ──────────────────────────────────────────────────────────────

    struct CreatorProfile {
        address creatorAddress;
        address nftContract;          // address(0) if NFT not enabled
        address subscriptionContract; // address(0) if stablecoin not enabled
        string username;
        string metadataURI;           // IPFS URI with creator profile metadata
        uint256 registeredAt;
        bool isActive;
    }

    struct NFTParams {
        bool enable;
        string name;
        string symbol;
        uint256 mintPrice;
        uint256 maxSupply;
        string baseURI;
    }

    struct SubParams {
        bool enable;
        uint256 monthlyPrice;
        address customStablecoin;
    }

    // ─── State Variables ──────────────────────────────────────────────────────

    /// @notice OnlyHold treasury address (receives 5% platform fees)
    address public treasury;

    /// @notice Default accepted stablecoin for new subscription contracts
    address public defaultStablecoin;

    /// @notice Stablecoin decimals (6 for USDC)
    uint8 public defaultStablecoinDecimals;

    /// @notice Mapping from creator address to their profile
    mapping(address => CreatorProfile) public creatorProfiles;

    /// @notice Mapping from username to creator address
    mapping(string => address) public usernameToAddress;

    /// @notice All registered creator addresses
    address[] private _creatorList;

    /// @notice Blacklisted addresses cannot register
    mapping(address => bool) public blacklisted;

    /// @notice Whether an address already registered as a creator
    mapping(address => bool) public isRegistered;

    // ─── Events ───────────────────────────────────────────────────────────────

    event CreatorLaunched(
        address indexed creator,
        string username,
        address nftContract,
        address subscriptionContract,
        uint256 timestamp
    );
    event CreatorDeactivated(address indexed creator);
    event TreasuryUpdated(address oldTreasury, address newTreasury);
    event DefaultStablecoinUpdated(address newStablecoin);

    // ─── Errors ───────────────────────────────────────────────────────────────

    error AlreadyRegistered();
    error UsernameTaken();
    error Blacklisted();
    error MustEnableAtLeastOne();
    error InvalidUsername();
    error NotRegistered();

    // ─── Constructor ──────────────────────────────────────────────────────────

    /**
     * @param _treasury               Platform treasury address
     * @param _defaultStablecoin      Default stablecoin (e.g. USDC on the chain)
     * @param _defaultStablecoinDecimals  Decimals (6 for USDC, 18 for DAI)
     */
    constructor(
        address _treasury,
        address _defaultStablecoin,
        uint8 _defaultStablecoinDecimals
    ) Ownable(msg.sender) {
        treasury = _treasury;
        defaultStablecoin = _defaultStablecoin;
        defaultStablecoinDecimals = _defaultStablecoinDecimals;
    }

    // ─── Creator Registration ─────────────────────────────────────────────────

    /**
     * @notice Register as a creator and optionally deploy NFT & Subscription contracts.
     *
     * @param username     Unique creator username (lowercase, alphanumeric + underscore)
     * @param metadataURI  IPFS URI with creator profile JSON
     * @param nft          NFT deployment parameters (set enable=false to skip)
     * @param sub          Subscription deployment parameters (set enable=false to skip)
     */
    function launchCreator(
        string calldata username,
        string calldata metadataURI,
        NFTParams calldata nft,
        SubParams calldata sub
    ) external returns (address nftContract, address subContract) {
        _validateLaunch(
            bytes(username).length,
            usernameToAddress[username] != address(0),
            nft.enable,
            sub.enable
        );

        nftContract = _deployNFT(nft);
        subContract = _deploySub(sub);

        _registerCreator(username, metadataURI, nftContract, subContract);
    }

    function _validateLaunch(
        uint256 usernameLen,
        bool usernameTaken,
        bool enableNFT,
        bool enableSub
    ) internal view {
        if (isRegistered[msg.sender]) revert AlreadyRegistered();
        if (blacklisted[msg.sender]) revert Blacklisted();
        if (!enableNFT && !enableSub) revert MustEnableAtLeastOne();
        if (usernameLen == 0 || usernameLen > 30) revert InvalidUsername();
        if (usernameTaken) revert UsernameTaken();
    }

    function _deployNFT(NFTParams calldata nft) internal returns (address) {
        if (!nft.enable) return address(0);
        return address(new OnlyHoldNFT(
            msg.sender,
            treasury,
            nft.name,
            nft.symbol,
            nft.mintPrice,
            nft.maxSupply,
            nft.baseURI
        ));
    }

    function _deploySub(SubParams calldata sub) internal returns (address) {
        if (!sub.enable) return address(0);
        address stablecoin = sub.customStablecoin != address(0)
            ? sub.customStablecoin
            : defaultStablecoin;
        return address(new OnlyHoldSubscription(
            msg.sender,
            treasury,
            stablecoin,
            defaultStablecoinDecimals,
            sub.monthlyPrice
        ));
    }

    function _registerCreator(
        string calldata username,
        string calldata metadataURI,
        address nftContract,
        address subContract
    ) internal {
        creatorProfiles[msg.sender] = CreatorProfile({
            creatorAddress: msg.sender,
            nftContract: nftContract,
            subscriptionContract: subContract,
            username: username,
            metadataURI: metadataURI,
            registeredAt: block.timestamp,
            isActive: true
        });

        usernameToAddress[username] = msg.sender;
        _creatorList.push(msg.sender);
        isRegistered[msg.sender] = true;

        emit CreatorLaunched(
            msg.sender,
            username,
            nftContract,
            subContract,
            block.timestamp
        );
    }

    // ─── Access Helpers ───────────────────────────────────────────────────────

    /**
     * @notice Check if `fan` has access to `creatorAddress`'s exclusive content.
     * @dev    Returns true if fan holds an NFT from the creator's collection
     *         OR has an active stablecoin subscription.
     * @param  creatorAddress  The creator's wallet address
     * @param  fan             The fan's wallet address
     * @return hasAccess       True if fan has access
     * @return via             "nft" | "subscription" | "none"
     */
    function checkAccess(address creatorAddress, address fan)
        external
        view
        returns (bool hasAccess, string memory via)
    {
        CreatorProfile memory profile = creatorProfiles[creatorAddress];

        // Check NFT membership
        if (profile.nftContract != address(0)) {
            if (OnlyHoldNFT(profile.nftContract).isMember(fan)) {
                return (true, "nft");
            }
        }

        // Check stablecoin subscription
        if (profile.subscriptionContract != address(0)) {
            if (OnlyHoldSubscription(profile.subscriptionContract).isSubscribed(fan)) {
                return (true, "subscription");
            }
        }

        return (false, "none");
    }

    /**
     * @notice Resolve a username to creator address + contract addresses.
     * @param  username  Creator's username
     * @return creator   Creator wallet address
     * @return nft       NFT contract address
     * @return sub       Subscription contract address
     */
    function resolveUsername(string calldata username)
        external
        view
        returns (
            address creator,
            address nft,
            address sub
        )
    {
        creator = usernameToAddress[username];
        if (creator == address(0)) return (address(0), address(0), address(0));
        CreatorProfile memory profile = creatorProfiles[creator];
        return (creator, profile.nftContract, profile.subscriptionContract);
    }

    // ─── Enumeration ──────────────────────────────────────────────────────────

    /// @notice Get total number of registered creators
    function creatorCount() external view returns (uint256) {
        return _creatorList.length;
    }

    /// @notice Get creator address by index
    function creatorAt(uint256 index) external view returns (address) {
        return _creatorList[index];
    }

    /// @notice Get all creator addresses (use with caution on large sets)
    function allCreators() external view returns (address[] memory) {
        return _creatorList;
    }

    // ─── Admin Functions ──────────────────────────────────────────────────────

    /// @notice Deactivate a creator (platform moderation)
    function deactivateCreator(address creatorAddress) external onlyOwner {
        if (!isRegistered[creatorAddress]) revert NotRegistered();
        creatorProfiles[creatorAddress].isActive = false;
        emit CreatorDeactivated(creatorAddress);
    }

    /// @notice Blacklist an address from registering
    function blacklist(address account, bool status) external onlyOwner {
        blacklisted[account] = status;
    }

    /// @notice Update the treasury address
    function setTreasury(address newTreasury) external onlyOwner {
        emit TreasuryUpdated(treasury, newTreasury);
        treasury = newTreasury;
    }

    /// @notice Update the default stablecoin
    function setDefaultStablecoin(address newStablecoin, uint8 decimals) external onlyOwner {
        defaultStablecoin = newStablecoin;
        defaultStablecoinDecimals = decimals;
        emit DefaultStablecoinUpdated(newStablecoin);
    }
}

contracts/OnlyHoldNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title OnlyHoldNFT
 * @dev ERC-721 Membership NFT contract for OnlyHold platform.
 *
 * Each creator deploys their own instance of this contract (via OnlyHoldFactory).
 * Holding an NFT from this contract grants lifetime access to the creator's
 * exclusive content. The NFT is transferable/tradeable on secondary markets.
 *
 * Revenue flow:
 *   Fan pays mintPrice (ETH)
 *   → 95% goes to creator (owner)
 *   → 5%  goes to OnlyHold platform treasury
 */
contract OnlyHoldNFT is
    ERC721,
    ERC721Enumerable,
    ERC721URIStorage,
    Ownable,
    ReentrancyGuard
{
    // ─── State Variables ──────────────────────────────────────────────────────

    /// @notice Creator's wallet address (receives 95% of mint revenue)
    address public immutable creator;

    /// @notice OnlyHold platform treasury (receives 5% platform fee)
    address public immutable treasury;

    /// @notice Mint price in ETH
    uint256 public mintPrice;

    /// @notice Maximum supply (0 = unlimited)
    uint256 public maxSupply;

    /// @notice Auto-incrementing token ID counter
    uint256 private _nextTokenId;

    /// @notice IPFS base URI for metadata
    string private _baseTokenURI;

    /// @notice Platform fee in basis points (500 = 5%)
    uint256 public constant PLATFORM_FEE_BPS = 500;

    /// @notice Whether minting is paused
    bool public mintingPaused;

    // ─── Events ───────────────────────────────────────────────────────────────

    event NFTMinted(address indexed to, uint256 indexed tokenId, uint256 price);
    event MintPriceUpdated(uint256 oldPrice, uint256 newPrice);
    event BaseURIUpdated(string newBaseURI);
    event MintingPaused(bool paused);

    // ─── Errors ───────────────────────────────────────────────────────────────

    error InsufficientPayment(uint256 required, uint256 provided);
    error MaxSupplyReached(uint256 maxSupply);
    error MintingIsPaused();
    error WithdrawFailed();
    error InvalidPrice();

    // ─── Constructor ──────────────────────────────────────────────────────────

    /**
     * @param _creator      Address of the content creator
     * @param _treasury     OnlyHold platform treasury address
     * @param _name         ERC-721 token name  (e.g. "Aria NFT Membership")
     * @param _symbol       ERC-721 symbol      (e.g. "ARIA")
     * @param _mintPrice    Mint price in wei
     * @param _maxSupply    Max token supply (0 = unlimited)
     * @param baseURI_      IPFS base URI for metadata
     */
    constructor(
        address _creator,
        address _treasury,
        string memory _name,
        string memory _symbol,
        uint256 _mintPrice,
        uint256 _maxSupply,
        string memory baseURI_
    ) ERC721(_name, _symbol) Ownable(_creator) {
        creator = _creator;
        treasury = _treasury;
        mintPrice = _mintPrice;
        maxSupply = _maxSupply;
        _baseTokenURI = baseURI_;
    }

    // ─── Minting ──────────────────────────────────────────────────────────────

    /**
     * @notice Mint a membership NFT.
     * @dev    Caller must send exactly `mintPrice` ETH.
     *         Revenue is split: 95% creator, 5% platform.
     * @param  to          Recipient of the NFT
     * @param  tokenURI_   Optional per-token metadata URI (can be empty to use base URI)
     */
    function mint(address to, string memory tokenURI_)
        external
        payable
        nonReentrant
    {
        if (mintingPaused) revert MintingIsPaused();
        if (msg.value < mintPrice) revert InsufficientPayment(mintPrice, msg.value);
        if (maxSupply > 0 && _nextTokenId >= maxSupply) revert MaxSupplyReached(maxSupply);

        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);

        if (bytes(tokenURI_).length > 0) {
            _setTokenURI(tokenId, tokenURI_);
        }

        // ── Revenue distribution ──────────────────────────────────────
        uint256 platformFee = (msg.value * PLATFORM_FEE_BPS) / 10_000;
        uint256 creatorShare = msg.value - platformFee;

        (bool sentToCreator, ) = creator.call{value: creatorShare}("");
        (bool sentToTreasury, ) = treasury.call{value: platformFee}("");
        if (!sentToCreator || !sentToTreasury) revert WithdrawFailed();

        emit NFTMinted(to, tokenId, msg.value);
    }

    /**
     * @notice Convenience function: mint to the caller's address.
     */
    function mintSelf(string memory tokenURI_) external payable nonReentrant {
        if (mintingPaused) revert MintingIsPaused();
        if (msg.value < mintPrice) revert InsufficientPayment(mintPrice, msg.value);
        if (maxSupply > 0 && _nextTokenId >= maxSupply) revert MaxSupplyReached(maxSupply);

        uint256 tokenId = _nextTokenId++;
        _safeMint(msg.sender, tokenId);

        if (bytes(tokenURI_).length > 0) {
            _setTokenURI(tokenId, tokenURI_);
        }

        uint256 platformFee = (msg.value * PLATFORM_FEE_BPS) / 10_000;
        uint256 creatorShare = msg.value - platformFee;

        (bool sentToCreator, ) = creator.call{value: creatorShare}("");
        (bool sentToTreasury, ) = treasury.call{value: platformFee}("");
        if (!sentToCreator || !sentToTreasury) revert WithdrawFailed();

        emit NFTMinted(msg.sender, tokenId, msg.value);
    }

    // ─── Access Check ─────────────────────────────────────────────────────────

    /**
     * @notice Check whether `account` holds at least one membership NFT.
     * @dev    Frontend calls this to gate exclusive content access.
     * @param  account  The wallet address to check
     * @return bool     True if the account is an active member
     */
    function isMember(address account) external view returns (bool) {
        return balanceOf(account) > 0;
    }

    /**
     * @notice Returns all token IDs held by `account`.
     */
    function tokensOfOwner(address account)
        external
        view
        returns (uint256[] memory)
    {
        uint256 count = balanceOf(account);
        uint256[] memory tokens = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            tokens[i] = tokenOfOwnerByIndex(account, i);
        }
        return tokens;
    }

    // ─── Owner Functions ──────────────────────────────────────────────────────

    /**
     * @notice Update mint price (creator only).
     * @param newPrice  New price in wei
     */
    function setMintPrice(uint256 newPrice) external onlyOwner {
        if (newPrice == 0) revert InvalidPrice();
        emit MintPriceUpdated(mintPrice, newPrice);
        mintPrice = newPrice;
    }

    /**
     * @notice Update base metadata URI (creator only).
     */
    function setBaseURI(string memory newBaseURI) external onlyOwner {
        _baseTokenURI = newBaseURI;
        emit BaseURIUpdated(newBaseURI);
    }

    /**
     * @notice Pause / unpause minting (creator only).
     */
    function setPaused(bool paused) external onlyOwner {
        mintingPaused = paused;
        emit MintingPaused(paused);
    }

    /**
     * @notice Airdrop membership NFTs to a list of addresses (creator only).
     * @dev    No payment required for airdrops.
     */
    function airdrop(address[] calldata recipients) external onlyOwner {
        for (uint256 i = 0; i < recipients.length; i++) {
            if (maxSupply > 0 && _nextTokenId >= maxSupply) break;
            uint256 tokenId = _nextTokenId++;
            _safeMint(recipients[i], tokenId);
            emit NFTMinted(recipients[i], tokenId, 0);
        }
    }

    // ─── View Helpers ─────────────────────────────────────────────────────────

    /// @notice Total number of NFTs minted so far
    function totalMinted() external view returns (uint256) {
        return _nextTokenId;
    }

    // ─── Overrides ────────────────────────────────────────────────────────────

    function _baseURI() internal view override returns (string memory) {
        return _baseTokenURI;
    }

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override(ERC721, ERC721Enumerable) returns (address) {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(
        address account,
        uint128 value
    ) internal override(ERC721, ERC721Enumerable) {
        super._increaseBalance(account, value);
    }

    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable, ERC721URIStorage)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/OnlyHoldSubscription.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title OnlyHoldSubscription
 * @dev Stablecoin-based subscription contract for OnlyHold platform.
 *
 * How it works:
 *   1. Creator sets a monthly price (e.g. 10 USDC).
 *   2. Fan deposits any multiple of the monthly price.
 *      e.g. 30 USDC = 3 months of access.
 *   3. Access is checked off-chain by reading `getSubscription()`.
 *      Access is active as long as `expiresAt > block.timestamp`.
 *   4. Fan can top-up anytime (extends expiry) or withdraw remaining balance
 *      (cancels remaining subscription).
 *   5. Creator withdraws accumulated earnings at any time.
 *
 * Revenue flow:
 *   Fan deposits USDC
 *   → Claimable by creator (95%) when they call `withdrawEarnings()`
 *   → 5% held for platform fee, claimable by treasury
 *
 * Supported stablecoins: USDC, USDT, DAI (or any ERC-20 the creator whitelists).
 */
contract OnlyHoldSubscription is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ─── Structs ──────────────────────────────────────────────────────────────

    struct SubscriberInfo {
        uint256 deposited;      // Total USDC deposited by this subscriber
        uint256 expiresAt;      // UNIX timestamp when subscription expires
        uint256 lastDeposit;    // Timestamp of last deposit
    }

    // ─── State Variables ──────────────────────────────────────────────────────

    /// @notice Creator's wallet address
    address public immutable creator;

    /// @notice OnlyHold platform treasury
    address public immutable treasury;

    /// @notice Accepted stablecoin (e.g. USDC at 6 decimals)
    IERC20 public immutable stablecoin;

    /// @notice Decimals of the stablecoin (6 for USDC/USDT, 18 for DAI)
    uint8 public immutable stablecoinDecimals;

    /// @notice Monthly subscription price in stablecoin base units
    ///         e.g. 10_000_000 = 10 USDC (6 decimals)
    uint256 public monthlyPrice;

    /// @notice Seconds in a 30-day month
    uint256 public constant MONTH_SECONDS = 30 days;

    /// @notice Platform fee in basis points (500 = 5%)
    uint256 public constant PLATFORM_FEE_BPS = 500;

    /// @notice Total undistributed earnings available for the creator to withdraw
    uint256 public pendingCreatorEarnings;

    /// @notice Total undistributed platform fees available for treasury to claim
    uint256 public pendingPlatformFee;

    /// @notice Subscriber data mapped by wallet address
    mapping(address => SubscriberInfo) public subscribers;

    /// @notice All subscriber addresses (for enumeration)
    address[] private _subscriberList;

    // ─── Events ───────────────────────────────────────────────────────────────

    event Subscribed(
        address indexed subscriber,
        uint256 amount,
        uint256 months,
        uint256 expiresAt
    );
    event BalanceWithdrawn(address indexed subscriber, uint256 amount);
    event CreatorWithdrew(address indexed creator, uint256 amount);
    event PlatformFeeWithdrawn(address indexed treasury, uint256 amount);
    event MonthlyPriceUpdated(uint256 oldPrice, uint256 newPrice);

    // ─── Errors ───────────────────────────────────────────────────────────────

    error InsufficientDeposit(uint256 required, uint256 provided);
    error NotMultipleOfMonthlyPrice(uint256 amount, uint256 monthlyPrice_);
    error NoEarningsToWithdraw();
    error NoBalanceToWithdraw();
    error InvalidPrice();
    error TransferFailed();

    // ─── Constructor ──────────────────────────────────────────────────────────

    /**
     * @param _creator            Creator's wallet
     * @param _treasury           OnlyHold treasury
     * @param _stablecoin         ERC-20 stablecoin address (e.g. USDC)
     * @param _stablecoinDecimals Decimals of the stablecoin (6 for USDC)
     * @param _monthlyPrice       Price per month in stablecoin base units
     */
    constructor(
        address _creator,
        address _treasury,
        address _stablecoin,
        uint8 _stablecoinDecimals,
        uint256 _monthlyPrice
    ) Ownable(_creator) {
        creator = _creator;
        treasury = _treasury;
        stablecoin = IERC20(_stablecoin);
        stablecoinDecimals = _stablecoinDecimals;
        monthlyPrice = _monthlyPrice;
    }

    // ─── Subscriber Functions ─────────────────────────────────────────────────

    /**
     * @notice Deposit stablecoin to subscribe.
     * @dev    `amount` must be a whole multiple of `monthlyPrice`.
     *         e.g. to subscribe for 3 months: amount = monthlyPrice * 3
     *
     *         If subscriber already has remaining time, new time is added on top.
     *         Caller must approve this contract to spend `amount` stablecoin first.
     *
     * @param amount  Amount of stablecoin in base units (e.g. 30_000_000 = 30 USDC)
     */
    function subscribe(uint256 amount) external nonReentrant {
        if (amount < monthlyPrice) revert InsufficientDeposit(monthlyPrice, amount);
        if (amount % monthlyPrice != 0) revert NotMultipleOfMonthlyPrice(amount, monthlyPrice);

        // Transfer stablecoin from subscriber
        stablecoin.safeTransferFrom(msg.sender, address(this), amount);

        // Calculate months purchased
        uint256 months = amount / monthlyPrice;
        uint256 addedSeconds = months * MONTH_SECONDS;

        // Extend subscription from max(now, current expiry)
        SubscriberInfo storage sub = subscribers[msg.sender];
        uint256 startFrom = block.timestamp > sub.expiresAt
            ? block.timestamp
            : sub.expiresAt;
        sub.expiresAt = startFrom + addedSeconds;
        sub.deposited += amount;
        sub.lastDeposit = block.timestamp;

        // Track new subscribers for enumeration
        if (sub.deposited == amount) {
            _subscriberList.push(msg.sender);
        }

        // ── Revenue accounting ────────────────────────────────────────
        uint256 platformFee = (amount * PLATFORM_FEE_BPS) / 10_000;
        uint256 creatorShare = amount - platformFee;

        pendingCreatorEarnings += creatorShare;
        pendingPlatformFee += platformFee;

        emit Subscribed(msg.sender, amount, months, sub.expiresAt);
    }

    /**
     * @notice Withdraw unused/remaining subscription balance.
     * @dev    Only refunds the proportion of time remaining from the LAST deposit.
     *         Previous months already consumed are non-refundable.
     *
     *         Remaining time is calculated as:
     *           remainingSeconds = expiresAt - now  (clamped to 0)
     *           refund = (remainingSeconds / MONTH_SECONDS) * monthlyPrice
     *                    (rounded down to whole months)
     */
    function withdrawBalance() external nonReentrant {
        SubscriberInfo storage sub = subscribers[msg.sender];

        if (sub.expiresAt <= block.timestamp) revert NoBalanceToWithdraw();

        uint256 remainingSeconds = sub.expiresAt - block.timestamp;
        uint256 remainingMonths = remainingSeconds / MONTH_SECONDS;

        if (remainingMonths == 0) revert NoBalanceToWithdraw();

        uint256 refundAmount = remainingMonths * monthlyPrice;

        // Reduce pending earnings proportionally
        uint256 platformFeeReduction = (refundAmount * PLATFORM_FEE_BPS) / 10_000;
        uint256 creatorReduction = refundAmount - platformFeeReduction;

        // Clamp to avoid underflow (safety check)
        if (pendingCreatorEarnings >= creatorReduction) {
            pendingCreatorEarnings -= creatorReduction;
        }
        if (pendingPlatformFee >= platformFeeReduction) {
            pendingPlatformFee -= platformFeeReduction;
        }

        // Cancel remaining subscription time
        sub.expiresAt = block.timestamp;
        sub.deposited -= refundAmount;

        stablecoin.safeTransfer(msg.sender, refundAmount);
        emit BalanceWithdrawn(msg.sender, refundAmount);
    }

    // ─── Creator Functions ────────────────────────────────────────────────────

    /**
     * @notice Withdraw accumulated earnings (creator only).
     */
    function withdrawEarnings() external onlyOwner nonReentrant {
        uint256 amount = pendingCreatorEarnings;
        if (amount == 0) revert NoEarningsToWithdraw();
        pendingCreatorEarnings = 0;
        stablecoin.safeTransfer(creator, amount);
        emit CreatorWithdrew(creator, amount);
    }

    /**
     * @notice Update monthly price (creator only).
     * @dev    Only affects NEW subscriptions. Existing ones are unaffected.
     */
    function setMonthlyPrice(uint256 newPrice) external onlyOwner {
        if (newPrice == 0) revert InvalidPrice();
        emit MonthlyPriceUpdated(monthlyPrice, newPrice);
        monthlyPrice = newPrice;
    }

    // ─── Platform Treasury Functions ──────────────────────────────────────────

    /**
     * @notice Withdraw accumulated platform fees (treasury only).
     */
    function withdrawPlatformFee() external nonReentrant {
        require(msg.sender == treasury, "Only treasury");
        uint256 amount = pendingPlatformFee;
        if (amount == 0) revert NoEarningsToWithdraw();
        pendingPlatformFee = 0;
        stablecoin.safeTransfer(treasury, amount);
        emit PlatformFeeWithdrawn(treasury, amount);
    }

    // ─── Access Control (called by frontend/backend) ──────────────────────────

    /**
     * @notice Check if a wallet currently has an active subscription.
     * @param  account  Wallet address to check
     * @return bool     True if subscription has not expired
     */
    function isSubscribed(address account) external view returns (bool) {
        return subscribers[account].expiresAt > block.timestamp;
    }

    /**
     * @notice Get full subscription details for an account.
     * @return deposited    Total USDC deposited
     * @return expiresAt    Subscription expiry timestamp
     * @return isActive     Whether subscription is currently active
     * @return remainingSeconds  Seconds until expiry (0 if expired)
     */
    function getSubscription(address account)
        external
        view
        returns (
            uint256 deposited,
            uint256 expiresAt,
            bool isActive,
            uint256 remainingSeconds
        )
    {
        SubscriberInfo memory sub = subscribers[account];
        isActive = sub.expiresAt > block.timestamp;
        remainingSeconds = isActive ? sub.expiresAt - block.timestamp : 0;
        return (sub.deposited, sub.expiresAt, isActive, remainingSeconds);
    }

    /**
     * @notice Returns all subscriber addresses.
     */
    function getSubscribers() external view returns (address[] memory) {
        return _subscriberList;
    }

    /**
     * @notice Returns the number of active subscribers at this moment.
     */
    function activeSubscriberCount() external view returns (uint256 count) {
        for (uint256 i = 0; i < _subscriberList.length; i++) {
            if (subscribers[_subscriberList[i]].expiresAt > block.timestamp) {
                count++;
            }
        }
    }
}

